WFJ.Data.add("gossip", {
  ["3f010f93b023727e"] = { "Parlami di qualcos'altro...", "." },
  ["3f0257a4201da5c3"] = { "A Durotar c'è molto da scavare in miniera, o così si dice. Tanto che qui a ⟦Razor Hill=Tranciacolle⟧ abbiamo proprio un istruttore di estrazione. Troverai Krunn accanto alla forgia rovente, nell'angolo nord-ovest del villaggio.", "." },
  ["3f0a6f56dfc2eaee"] = { "Salute, {class}. Vieni a cercare le benedizioni del Signore del Vento?", "." },
  ["3f0b8ce0eadd3f0a"] = { "Hai superato ogni insegnamento che potrei offrirti. Va' con la benedizione della Madre Terra. Cerca il tauren Tarn nelle botteghe a nord-ovest dell'altopiano centrale del Picco del Tuono. Lasciati guidare dalla sua saggezza.", "." },
  ["3f0d08c2aee54ccf"] = { "Gli spiriti sono inquieti!", "." },
  ["3f0fc069be1ee74e"] = { "Un panino? Cosa? Mi stai preparando un panino, papà?", "." },
  ["3f1024427acdb6c8"] = { "Ciao! Mi chiamo Gregan. Cosa posso fare per te?", "." },
  ["3f11c586ad564439"] = { "Chi dice che gli orchi non sono svegli? Ci vuole un bel cervello per fare l'ingegnere!", "." },
  ["3f14ba1b423fa380"] = { "Aiuto!! Te l'avevo detto che questo posto era maledetto!", "." },
  ["3f1723567dd6b858"] = { "Salute, cittadini! Forse presto la marea girerà a nostro favore e la piaga finirà.", "." },
  ["3f1c16fbe3dbdd68"] = { "Credo che Simone ti stesse cercando poco fa, {name}. Ci hai già parlato?", "." },
  ["3f1e32ebad680640"] = { "Buon Winter's Vale a te, amico!", "." },
  ["3f2579762d9c12ca"] = { "Non... è... il momento... migliore, {name}. Devo concen... trarmi.", "." },
  ["3f274520718674d1"] = { "Fantastico, allora! Sistemiamo questo coso per te.", "." },
  ["3f27e32ffebaccbc"] = { "Ah, bella domanda.\n\nSe preferisci cacciare all'aperto, ci sono elementali qui nelle ⟦Plaguelands=Terre Infette⟧, ad Azshara, nelle ⟦Burning Steppes=Steppe Ardenti⟧, a ⟦Felwood=Vilbosco⟧, a ⟦Silithus=Silitus⟧, a ⟦Winterspring=Fontefredda⟧ e perfino nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.\n\nSe sei il tipo che ride in faccia al pericolo, forse dovresti visitare ⟦Dire Maul=Maglio Infausto⟧. Ho sentito dire che tra le sue mura si trovano moltissime aberrazioni elementali. Faresti bene anche a dare la caccia agli elementali al servizio dei nani ⟦Dark Iron=Ferroscuro⟧ dei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.", "." },
  ["3f28cdd8237b284f"] = { "Glyx e io abbiamo un accordo: lui mi rifornisce e io lo faccio diventare ricco. Sul serio! Quello che quel pirata mi fa pagare per un misero sacchetto di Kingsblood stropicciato... è abbastanza da far piangere un goblin adulto.", "." },
  ["3f2d54afc7afd3a4"] = { "Per Broxigar!", "." },
  ["3f2e527a90618cda"] = { "Cos'è il Juju?", "." },
  ["3f2e72274e8d8f1c"] = { "Prendilo, allora. A quanto pare Zygand è troppo occupato per affrontare il penoso viaggio fin qui e recuperarlo di persona.", "." },
  ["3f3586f7e41e824d"] = { "La Stormpike Aid Station si trova a Dun Baldar, proprio fuori dalla caserma di Dun Baldar.\n\nAl momento è controllata dall'⟦Horde=Orda⟧.", "." },
  ["3f35f225e1f5991c"] = { "Sì, ho visto la sciamana che cerchi. L'ultima volta che l'ho vista era a ovest di qui. Si nasconde sulle colline sopra la tribù dei ⟦Razormane=Chiomaguzza⟧. Se sei abbastanza in gamba, troverai un sentiero che porta alla sua capanna sulle colline. Non è molto a nord di qui. Quel sentiero dovrebbe permetterti di trovarla senza dover combattere contro i verrospini.", "." },
  ["3f3a560497a1b8da"] = { "Povero Dorius. Se mai metto le mani su quei Ferroscuro, giuro che...", "." },
  ["3f3aa280d015f1d9"] = { "Wulan a ⟦Shadowprey Village=Predombra⟧ può venderti il «⟦Expert Cookbook=Ricettario per Esperti⟧». Ti servirà, se vuoi migliorare.", "." },
  ["3f3f5ca5eb48f84e"] = { "C'è un'ottima scuoiatrice che vive nella casa vicino al ⟦Crystal Lake=Lago di Cristallo⟧. Saprà di certo mostrarti come muovere i primi passi nella professione dello scuoiatore.", "." },
  ["3f4048f507617199"] = { "Siamo quasi in salvo. Da qui si corre. Cerca di non restare troppo indietro! VIA!", "." },
  ["3f44c71cd9b43539"] = { "Sono <pronto/pronta> per l'illusione, Myranda.", "." },
  ["3f460f76ad8ada0e"] = { "Parla con Prate Cloudseer a ⟦Thousand Needles=Millepicchi⟧.", "." },
  ["3f51398a69cb1a18"] = { "A rapporto dall'esplorazione!....Eccellente!", "." },
  ["3f57a3a96b232023"] = { "Li uccidiamo per l'impertinenza di aver disturbato il nostro sonno?", "." },
  ["3f59ae796c69e8f6"] = { "Vittoria per l'⟦Horde=Orda⟧!", "." },
  ["3f5f84a82591b80e"] = { "Non ho tempo per chiacchierare, <cittadino/cittadina>, ma se vuoi darci una mano contro gli orchi, troverò il modo di impiegarti.", "." },
  ["3f63f98e29b13b7f"] = { "Ah, ci voleva proprio!", "." },
  ["3f6d811e9e3bc350"] = { "Meraviglioso, {name}. Con tutti e tre i campioni raccolti, posso creare per te una fiala dell'acqua più pura che una creatura vivente possa trovare. Servirà nelle prossime tappe del tuo rito di passaggio.\n\nSono lieta di annoverarti tra i nostri, {name}. Rendi orgogliosi tutti gli {class}, e non vedo l'ora di sentir parlare delle tue imprese in futuro.", "." },
  ["3f70d79987be3b41"] = { "⟦Zul'Farrak=Zul'farrak⟧", "." },
  ["3f70f7d0cb896a2b"] = { "Ho finito il tuo elmo, {name}.", "." },
  ["3f7457101d9379ae"] = { "Iuhuu, ci siamo! Tutti hanno raccolto tutto, e proprio ora lo stiamo trasportando in zeppelin a ⟦Silithus=Silitus⟧. L'ultimo carico dovrebbe arrivare in meno di un giorno. Quando sarà tutto là e lo scettro sarà ricomposto, potrà cominciare la guerra contro quei lerci insetti. Come si suol dire: «Spedito!»", "." },
  ["3f758ac80cd43f7e"] = { "Questa pianta spicca tra la normale flora di Teldrassil ed emana uno strano bagliore violaceo.", "." },
  ["3f7c29b0fc014523"] = { "Il Gran Crociato mi ha incaricato di distruggere te e i tuoi nuovi amici, Taelan, ma sappi questo: lo faccio per piacere, non per obbligo o dovere.", "." },
  ["3f7f8acf168b8a0d"] = { "Il Dio del Sangue, lo Scortica Anime, è stato sconfitto! Non siamo più in pericolo!", "." },
  ["3f8c3578ad2106fd"] = { "Dei messaggeri di ⟦Ravenholdt=Corvolesto⟧ mi hanno consegnato questa lettera stamattina. È indirizzata a te, {name}.", "." },
  ["3fce7f086dca46fa"] = { "Sia lodata la Luce, finalmente qualcuno ha risposto alla chiamata.", "." },
  ["3fdba1334f142b8a"] = { "La locanda? Ah, vuoi buttar giù un po' delle migliori birre che ⟦Ironforge=Forgiardente⟧ ha da offrire? È alla Stonefire Tavern che devi andare.\n\nLa trovi subito a sinistra dell'ingresso di ⟦Ironforge=Forgiardente⟧ se stai arrivando, o a destra se te ne stai andando.", "." },
  ["3fe1d84e387ce0d6"] = { "Io. . .io. . .non. . .mi. . .sento. . .bene. . .", "." },
  ["3fe2b59a19aeec39"] = { "Come osi profanare questo luogo antico!", "." },
  ["3fe48d3028636b07"] = { "Voglio vedere la tua merce di stagione.", "." },
  ["3fe789397b6fcd53"] = { "A-Me, casa. A-Me va a casa! {name}, no fermare A-Me.", "." },
  ["3feaa06a8001c455"] = { "%s si sovraccarica!", "." },
  ["3febbdd767d07680"] = { "Intrusi!!", "." },
  ["3ff1fa324ab9df5c"] = { "Saluti e omaggi dal maniero di ⟦Ravenholdt=Corvolesto⟧, <avventuriero/avventuriera>.", "." },
  ["3ffe64bd43ae4c4c"] = { "$950w, soldato.", "." },
})
